  const Library = {};
  Library.getIdentifiers = src => getPlayerIdentifiers(src) || [];
  Library.getIdentifier = (src, type) => {
    for (const id of Library.getIdentifiers(src)) {
      if (id.startsWith(type)) {
        return id;
      }
    }
    return null;
  };
  Library.getLicense = src => Library.getIdentifier(src, "license:");
  Library.getLicense2 = src => Library.getIdentifier(src, "license2:");
  Library.getSteam = src => Library.getIdentifier(src, "steam:");
  Library.getDiscord = src => Library.getIdentifier(src, "discord:");
  Library.getFivem = src => Library.getIdentifier(src, "fivem:");
  Library.getIp = src => GetPlayerEndpoint(src);
  Library.executeQuery = (query, params) => new Promise(resolve => {
    if (exports.oxmysql && exports.oxmysql.execute) {
      exports.oxmysql.execute(query, params || [], r => resolve(r || []));
    } else {
      resolve([]);
    }
  });
  Library.insertQuery = (query, params) => new Promise(resolve => {
    if (exports.oxmysql && exports.oxmysql.insert) {
      exports.oxmysql.insert(query, params || [], id => resolve(id));
    } else {
      resolve(0);
    }
  });
  Library.scalarQuery = (query, params) => new Promise(resolve => {
    if (exports.oxmysql && exports.oxmysql.scalar) {
      exports.oxmysql.scalar(query, params || [], r => resolve(r));
    } else {
      resolve(null);
    }
  });
  exports("GetLibrary", () => Library);
  exports("GetLicense", Library.getLicense);
  exports("GetSteam", Library.getSteam);
  exports("GetDiscord", Library.getDiscord);
  exports("GetFivem", Library.getFivem);

