  // Helper to parse incoming header
  function parseHeader(header) {
    if (!header) {
      return {
        id: 0,
        origin: ""
      };
    }
    if (typeof header === "object") {
      return header;
    }
    if (typeof header === "string") {
      try {
        return JSON.parse(header);
      } catch (e) {}
    }
    return {
      id: 0,
      origin: ""
    };
  }

  // Handle single RPC invocation
  async function handleRpcRequest(src, rpcName, header, params) {
    const parsed = parseHeader(header);
    const origin = parsed.origin || "";
    const id = parsed.id || 0;
    let result = null;
    let success = true;
    try {
      if (rpcName.startsWith("__npx_groups:manager:") && rpcName.endsWith(":init")) {
        result = [];
      } else if (customHandlers.has(rpcName)) {
        result = await customHandlers.get(rpcName)(src, ...(params || []));
      } else if (defaultHandlers[rpcName]) {
        result = await defaultHandlers[rpcName](src, ...(params || []));
      } else {
        result = [];
      }
    } catch (err) {
      console.warn(`[NPX-RPC] Error in handler for "${rpcName}":`, err.message);
      success = false;
      result = err.message;
    }
    if (result === undefined || result === null) {
      result = [];
    }

    // Send response back to the client
    if (origin) {
      emitNet(`__rpc_res:${origin}`, src, id, [success, result]);
    }
  }

  // Handle Lua RPC invocation
  async function handleLuaRpcRequest(src, rpcName, origin, callId, params, isPackaged) {
    let result = null;
    try {
      if (customHandlers.has(rpcName)) {
        result = await customHandlers.get(rpcName)(src, ...(params || []));
      } else if (defaultHandlers[rpcName]) {
        result = await defaultHandlers[rpcName](src, ...(params || []));
      } else {
        result = [];
      }
    } catch (err) {
      result = [];
    }
    if (result === undefined || result === null) {
      result = [];
    }
    emitNet("rpc:response", src, origin, callId, [result], isPackaged);
  }

